// Compares each price with the one stored on an earlier check and reports the moves at or past your threshold.
// The stored prices live in this workflow's static data. n8n keeps them only on runs the schedule starts after
// the workflow is published, so a manual run always behaves like a first run.
const threshold = Number($('Settings').first().json.moveThresholdPercent);
const store = $getWorkflowStaticData('global');
const page = $input.first().json;
const events = page.data ?? [];
const now = Date.now();
const prices = { ...store.prices }; // 'event|venue|market|outcome' -> [price, kick-off in ms]
const moves = [];
let watching = 0;

for (const ev of events) {
  const kickOff = Date.parse(ev.commence_time);
  const event = ev.home_team && ev.away_team ? `${ev.home_team} v ${ev.away_team}` : ev.sport_title;
  for (const venue of ev.bookmakers ?? []) {
    for (const market of venue.markets ?? []) {
      for (const o of market.outcomes ?? []) {
        const price = o.price ?? o.back_price; // bookmakers send price, exchanges back_price
        if (!(price > 1)) continue;
        watching++;
        const key = [ev.id, venue.key, market.key, o.name].join('|');
        const before = prices[key]?.[0];
        prices[key] = [price, kickOff];
        const change = before ? ((price - before) / before) * 100 : 0;
        if (change && Math.abs(change) >= threshold) {
          moves.push({ event, kickOff, venue: venue.title, market: market.key, outcome: o.name, before, price, change });
        }
      }
    }
  }
}

// Forget outcomes whose event has started, so the stored data stays small
for (const key of Object.keys(prices)) if (!(prices[key][1] > now)) delete prices[key];
store.prices = prices;

const count = (k, word) => `${k} ${word}${k === 1 ? '' : 's'}`;
if (!store.startedAt) {
  store.startedAt = new Date(now).toISOString();
  const more = page.meta?.next_cursor ? `\nYour filters match ${page.meta.total} events: each check reads the first ${events.length} by kick-off.` : '';
  const what = events.length ? `Watching ${count(watching, 'price')} on ${count(events.length, 'event')}.` : 'No events match your filters right now.';
  return [{ json: { text: `${what} You will get a message here when a price moves by ${threshold}% or more.${more}` } }];
}
if (!moves.length) return [];

const when = (ms) => new Date(ms).toLocaleString('en-GB', { timeZone: 'Europe/London', weekday: 'short', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' });
moves.sort((a, b) => Math.abs(b.change) - Math.abs(a.change));
const lines = moves.slice(0, 20).map((m) =>
  `${m.event}, ${when(m.kickOff)}\n${m.venue} ${m.market}, ${m.outcome}: ${m.before} → ${m.price} (${m.change > 0 ? '+' : ''}${m.change.toFixed(1)}%)`);
const rest = moves.length > 20 ? `\n\nAnd ${moves.length - 20} more.` : '';
return [{ json: { text: `Price moves of ${threshold}% or more:\n\n${lines.join('\n\n')}${rest}` } }];
